<?php
declare(strict_types=1);require_once __DIR__.'/../config/api.php';$u=requireUser($pdo);if($_SERVER['REQUEST_METHOD']==='GET'){$s=$pdo->prepare('SELECT id,subject,message,status,admin_reply,replied_at,created_at,updated_at FROM support_tickets WHERE user_id=? ORDER BY created_at DESC');$s->execute([$u['user_id']]);respond(['success'=>true,'data'=>$s->fetchAll(PDO::FETCH_ASSOC)]);}if($_SERVER['REQUEST_METHOD']==='POST'){$d=jsonInput();$subject=trim((string)($d['subject']??''));$message=trim((string)($d['message']??''));if($subject===''||$message==='')respond(['success'=>false,'message'=>'subject and message are required'],422);$s=$pdo->prepare('INSERT INTO support_tickets(user_id,subject,message) VALUES(?,?,?)');$s->execute([$u['user_id'],$subject,$message]);respond(['success'=>true,'message'=>'Support request submitted','data'=>['ticket_id'=>(int)$pdo->lastInsertId(),'status'=>'open']],201);}respond(['success'=>false,'message'=>'Method not allowed'],405);
